<template><div class="page"><h2>工作台</h2><section class="cards"><div v-for="item in cards" :key="item.label" class="card"><span>{{ item.label }}</span><strong>{{ item.value }}</strong></div></section><el-card><template #header>公会流水（金币）</template><el-descriptions :column="4"><el-descriptions-item label="日流水">{{ data.dayFlow || 0 }}</el-descriptions-item><el-descriptions-item label="周流水">{{ data.weekFlow || 0 }}</el-descriptions-item><el-descriptions-item label="月流水">{{ data.monthFlow || 0 }}</el-descriptions-item><el-descriptions-item label="总流水">{{ data.totalFlow || 0 }}</el-descriptions-item></el-descriptions></el-card><el-card class="space"><template #header>额度与授权余量</template><span class="muted">新人礼包、会长礼包、大哥礼包、靓号及封禁额度暂未配置数据源。</span></el-card><el-card class="space"><template #header>最近操作</template><span class="muted">暂未启用操作日志。</span></el-card></div></template>
<script setup>import { getExternalWorkbench } from '@/api/external/manager'; const data = reactive({}); const cards = computed(() => [{ label: 'BD Leader', value: data.bdLeaderCount || 0 }, { label: 'BD', value: data.bdCount || 0 }, { label: '公会', value: data.guildCount || 0 }, { label: '主播', value: data.anchorCount || 0 }, { label: '今日团队流水（金币）', value: data.dayFlow || 0 }]); getExternalWorkbench().then(res => Object.assign(data, res.data))</script>
<style scoped>.page{padding:20px}.cards{display:grid;grid-template-columns:repeat(5,minmax(130px,1fr));gap:16px;margin:16px 0}.card{border:1px solid #dcdfe6;padding:18px;background:#fff}.card span{display:block;color:#909399}.card strong{display:block;font-size:24px;margin-top:10px}.space{margin-top:16px}.muted{color:#909399}@media(max-width:900px){.cards{grid-template-columns:repeat(2,1fr)}}</style>
